const paramDefs=[["factory_days","工厂生产周期（天）"],["domestic_days","国内物流运输（天）"],["crossborder_days","泰国跨境物流（天）"],["safety_days","安全库存（天）"],["emergency_days","极紧急阈值（天）"],["attention_days","关注阈值（目标周期后天数）"],["stale_days","快照过期阈值（天）"],["moq","MOQ 最小采购量"],["pack","整箱采购倍数"]];
const paramHelp={
factory_days:"从下单到工厂交货需要多少天。时间越长，就要越早下单、准备越多库存；填太短可能断货，填太长可能积压。换工厂、排产或旺季交期变化时调整；每个 SKU 可单独填写。",
domestic_days:"工厂交货到国内集货/出口交接需要多少天。调高会更早补货，调低会减少准备量；低估运输可能断货，过高会占用库存。国内仓、路线或承运商变化时调整。",
crossborder_days:"国内出口交接到泰国仓可入库需要多少天，含跨境运输和清关。越长越早下单；过低容易清关延误断货，过高容易备货过多。物流路线、清关速度或旺季变化时调整。",
safety_days:"正常到货周期之外多留几天库存，防销量增加或运输延误。调高会增加目标库存；太低容易断货，太高容易压货。销量波动大、物流不稳时可提高，稳定后可降低。",
emergency_days:"预计几天内会断货就列为 P0 极紧急。调高会让更多商品提前进入紧急处理，调低可能发现太晚；太高会产生过多紧急提醒。按团队催货、调拨需要的反应时间调整。",
attention_days:"在目标覆盖周期后再留多少天作为关注范围。调高会更早出现 P2 提醒，调低提醒更少；太低可能错过准备时间，太高可能提醒过多。按日常查看库存的频率调整。",
stale_days:"库存快照超过多少天就提醒数据过期。调低会更严格地提醒重新导入；太高可能使用陈旧数据，太低会频繁提示。按真实库存表更新频率调整，不能用导入时间冒充快照日期。",
moq:"供应商每次至少接受采购多少件。只在有正数补货需求时生效，调高可能多采购；太高容易积压，太低可能供应商不接单。供应商起订要求变化时调整。",
pack:"每箱装多少件，采购数量向上凑成整箱倍数。调大可能增加最后凑箱量；填错可能采购数量不符合包装或造成积压。包装规格变化时调整，散件采购可填 1。",
w0:"越重视最近 7 天，系统越快跟上近期销量变化。调高遇到大促容易多备货，调低遇到突然增长可能补货太慢。短期活动或趋势变化时调整，三个权重合计必须是 100%。",
w1:"重视近 15 天，作为近期和长期销量之间的折中。调高可减轻单周波动，但可能反应不够快；太低会减少这段信息的影响。销量刚发生变化或单周异常时调整，三个权重合计 100%。",
w2:"越重视近 30 天，估计越平稳。调高可能错过最近增长或下滑，调低可能被短期波动带偏。稳定常卖款可提高、快速变化款可降低；三个权重合计 100%。",
assumed:"“暂定假设”表示交期还没有核实，页面会一直提示；“已核实”表示已按工厂和物流实际确认。它只改变来源提示，不会替你改变天数或提升预测准确度；未核实时不要选已核实。",
clearance:"标记清仓后默认不做常规补货，库存和销量仍统计。人工确认正常销售会解除禁补；恢复自动规则则按清仓表映射判断。误标会漏采购，误解除会买回清仓款，商品策略变化时调整。"
};
